{
  "permissions": {
    "allow": [
      "Bash(ls:*)"
    ]
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "^(Bash|.*[Bb]ash.*)$",
        "hooks": [
          {
            "type": "command",
            "command": "agentmux-bashwrap hook"
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "matcher": "manual",
        "hooks": [
          {
            "type": "command",
            "command": "agentmux-bashwrap precompact --trigger=manual"
          }
        ]
      },
      {
        "matcher": "auto",
        "hooks": [
          {
            "type": "command",
            "command": "agentmux-bashwrap precompact --trigger=auto"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 1"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 2"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 3"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 4"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 5"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 6"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 7"
          },
          {
            "type": "command",
            "command": "agentmux-bashwrap sessionstart --part 8"
          }
        ]
      }
    ]
  },
  "attribution": {
    "commit": "",
    "pr": ""
  }
}
